using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly string baseUrl;

    private int status = 200;
    private string responseBody = "";
    private string? method;
    private string? path;
    private string? contentType;
    private string? requestBody;

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        baseUrl = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(baseUrl);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint()
    {
        responseBody = """{"status":"approved"}""";

        await Authorize("ORD-7", new Money(12.5m, "eur"));

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(requestBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        responseBody = """{"status":"approved"}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        responseBody = """{"status":"declined"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        responseBody = """{"id":"abc","status":"approved","risk":{"score":3}}""";

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task An_unrecognised_or_missing_status_is_never_treated_as_approved()
    {
        responseBody = """{"status":"pending"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());

        responseBody = "{}";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_read_as_declined()
    {
        status = 402;
        responseBody = """{"error":"card_refused"}""";

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_surface_as_failures_not_as_decisions(int errorStatus)
    {
        status = errorStatus;
        responseBody = """{"status":"approved"}""";

        await Assert.ThrowsAsync<HttpRequestException>(() => Authorize());
    }

    [Fact]
    public async Task A_malformed_answer_surfaces_as_a_failure()
    {
        responseBody = "<html>oops</html>";

        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize());
    }

    private Task<AuthorizationOutcome> Authorize(string reference = "ORD-1", Money? amount = null)
    {
        var serving = Serve();
        var call = new HttpPaymentGateway(client)
            .AuthorizeAsync(reference, amount ?? new Money(10m, "EUR"), CancellationToken.None);
        return Complete(call, serving);
    }

    private static async Task<AuthorizationOutcome> Complete(Task<AuthorizationOutcome> call, Task serving)
    {
        try { return await call; }
        finally { await serving; }
    }

    private async Task Serve()
    {
        var context = await listener.GetContextAsync();
        var request = context.Request;
        method = request.HttpMethod;
        path = request.Url!.AbsolutePath;
        contentType = request.ContentType;
        using (var reader = new StreamReader(request.InputStream, request.ContentEncoding))
            requestBody = await reader.ReadToEndAsync();

        var bytes = Encoding.UTF8.GetBytes(responseBody);
        context.Response.StatusCode = status;
        context.Response.ContentType = "application/json";
        context.Response.ContentLength64 = bytes.Length;
        await context.Response.OutputStream.WriteAsync(bytes);
        context.Response.Close();
    }

    private static int FreePort()
    {
        var tcp = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        tcp.Start();
        var port = ((IPEndPoint)tcp.LocalEndpoint).Port;
        tcp.Stop();
        return port;
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
